package com.jobworker.processing

import java.io.*
import java.util.zip.*
import javax.crypto.*
import javax.crypto.spec.*
import java.security.*
import java.util.concurrent.atomic.AtomicLong

object Config {
    const val MAX_COMPRESSED_SIZE = 10L * 1024 * 1024  // 10MB compressed
    const val MAX_DECOMPRESSED_SIZE = 100L * 1024 * 1024  // 100MB decompressed
    const val MAX_ENTRIES = 1000
    const val CHUNK_SIZE = 8192
    const val AES_KEY_SIZE = 256
    const val STORAGE_PATH = "/var/data/processed"
}

class SecureStorage(private val masterKey: ByteArray) {
    private val cipher = Cipher.getInstance("AES/GCM/NoPadding")

    fun encrypt(data: ByteArray): ByteArray {
        val iv = ByteArray(12).also { SecureRandom().nextBytes(it) }
        val spec = GCMParameterSpec(128, iv)
        val keySpec = SecretKeySpec(masterKey, "AES")
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, spec)
        val encrypted = cipher.doFinal(data)
        return iv + encrypted
    }

    fun store(filename: String, data: ByteArray) {
        val sanitized = filename.replace(Regex("[^a-zA-Z0-9._-]"), "_")
        val encrypted = encrypt(data)
        File(Config.STORAGE_PATH, sanitized).writeBytes(encrypted)
    }
}

class DecompressionGuard {
    private val totalBytesRead = AtomicLong(0)
    private val entryCount = AtomicLong(0)

    fun checkEntryLimit(): Boolean {
        return entryCount.incrementAndGet() <= Config.MAX_ENTRIES
    }

    fun accountBytes(count: Long): Boolean {
        return totalBytesRead.addAndGet(count) <= Config.MAX_DECOMPRESSED_SIZE
    }

    fun getRatio(compressedSize: Long): Double {
        val decompressed = totalBytesRead.get()
        if (compressedSize == 0L) return Double.MAX_VALUE
        return decompressed.toDouble() / compressedSize.toDouble()
    }

    fun reset() {
        totalBytesRead.set(0)
        entryCount.set(0)
    }
}

class ZipJobWorker(masterKey: ByteArray) {
    private val storage = SecureStorage(masterKey)
    private val guard = DecompressionGuard()

    fun processJob(jobId: String, inputStream: InputStream, compressedSize: Long): Result<Int> {
        if (compressedSize > Config.MAX_COMPRESSED_SIZE) {
            return Result.failure(SecurityException("Compressed size exceeds limit"))
        }

        guard.reset()
        var processedEntries = 0

        return try {
            val buffered = BufferedInputStream(inputStream, Config.CHUNK_SIZE)
            val zipStream = ZipInputStream(buffered)

            var entry = zipStream.nextEntry
            while (entry != null) {
                if (!guard.checkEntryLimit()) {
                    return Result.failure(SecurityException("Too many entries in archive"))
                }

                if (!entry.isDirectory) {
                    val content = readEntryWithGuard(zipStream, entry, compressedSize)
                    if (content != null) {
                        storage.store("${jobId}_${entry.name}", content)
                        processedEntries++
                    } else {
                        return Result.failure(SecurityException("Decompression limit exceeded"))
                    }
                }

                zipStream.closeEntry()
                entry = zipStream.nextEntry
            }

            zipStream.close()
            Result.success(processedEntries)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    private fun readEntryWithGuard(
        zipStream: ZipInputStream,
        entry: ZipEntry,
        compressedSize: Long
    ): ByteArray? {
        val outputBuffer = ByteArrayOutputStream()
        val buffer = ByteArray(Config.CHUNK_SIZE)
        var bytesRead: Int

        while (zipStream.read(buffer).also { bytesRead = it } != -1) {
            outputBuffer.write(buffer, 0, bytesRead)

            if (!guard.accountBytes(bytesRead.toLong())) {
                return null
            }

            // Ratio check uses per-entry compressed size from metadata
            val entryCompressedSize = entry.compressedSize
            if (entryCompressedSize > 0) {
                val currentRatio = outputBuffer.size().toDouble() / entryCompressedSize.toDouble()
                if (currentRatio > 100.0) {
                    return null
                }
            }
        }

        return outputBuffer.toByteArray()
    }
}

fun main() {
    val key = ByteArray(32).also { SecureRandom().nextBytes(it) }
    val worker = ZipJobWorker(key)

    // Simulate receiving a job
    val testData = ByteArrayInputStream(createTestZip())
    val result = worker.processJob("job-001", testData, 1024L)
    println("Result: $result")
}

fun createTestZip(): ByteArray {
    val baos = ByteArrayOutputStream()
    val zos = ZipOutputStream(baos)
    zos.putNextEntry(ZipEntry("test.txt"))
    zos.write("Hello World".toByteArray())
    zos.closeEntry()
    zos.close()
    return baos.toByteArray()
}
